BEGIN;
DO $$
DECLARE org bigint; un bigint; oc bigint; bank bigint; pi bigint; other_pi bigint; oid bigint; other_order bigint; movement bigint; second_movement bigint; n bigint;
BEGIN
 INSERT INTO public.organizations(title) VALUES('Platby pořadatele') RETURNING id INTO org;
 INSERT INTO public.units(organization,title) VALUES(org,'Spolek') RETURNING id INTO un;
 INSERT INTO public.occasions(organization,unit,title,link,start_time,end_time) VALUES(org,un,'Ples',gen_random_uuid()::text,now(),now()+interval '1 day') RETURNING id INTO oc;
 INSERT INTO eshop.bank_accounts(title,type) VALUES('Účet','FIO') RETURNING id INTO bank;
 INSERT INTO eshop.unit_bank_accounts(unit,bank_account) VALUES(un,bank);
 INSERT INTO public.notification_center_organizations(organization,initialized_at) VALUES(org,now()-interval '1 day');
 INSERT INTO eshop.payment_info(variable_symbol,amount,currency_code,bank_account,paid) VALUES(100,100,'CZK',bank,0) RETURNING id INTO pi;
 INSERT INTO eshop.payment_info(variable_symbol,amount,currency_code,bank_account,paid) VALUES(101,100,'CZK',bank,0) RETURNING id INTO other_pi;
 INSERT INTO eshop.orders(occasion,payment_info,state,price,currency_code,order_symbol,order_sequence) VALUES(oc,pi,'ordered',100,'CZK',public.generate_order_symbol(),1) RETURNING id INTO oid;
 INSERT INTO eshop.orders(occasion,payment_info,state,price,currency_code,order_symbol,order_sequence) VALUES(oc,other_pi,'ordered',100,'CZK',public.generate_order_symbol(),2) RETURNING id INTO other_order;
 INSERT INTO eshop.transactions(amount,currency,bank_account_id,date,transaction_type) VALUES(20,'CZK',bank,now(),'manual') RETURNING id INTO movement;
 PERFORM public.apply_transaction_pairing(movement,pi,'test','system');
 PERFORM public.apply_transaction_pairing(movement,pi,'test','system');
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org AND kind='order_payment_received'),1::bigint,'replay does not create another payment receipt');
 INSERT INTO eshop.transactions(amount,currency,bank_account_id,date,transaction_type) VALUES(30,'CZK',bank,now(),'manual') RETURNING id INTO second_movement;
 PERFORM public.apply_transaction_pairing(second_movement,pi,'test','system');
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org AND kind='order_payment_received'),2::bigint,'a distinct top-up has a distinct fact');
 PERFORM assert_true(NOT EXISTS(SELECT 1 FROM public.notification_center_events WHERE organization=org AND kind='order_payment_received' AND data->'count'<>'null'::jsonb),'financial facts have no ticket/person contribution');
 ALTER TABLE eshop.order_product_ticket RENAME TO payment_fact_ticket_probe;
 EXECUTE 'DISCARD PLANS';
 PERFORM public.notification_center_event_facts_internal(e) FROM public.notification_center_events e WHERE organization=org AND kind='order_payment_received';
 ALTER TABLE eshop.payment_fact_ticket_probe RENAME TO order_product_ticket;
 PERFORM public.recalculate_order_payment_status(oid);
 UPDATE eshop.orders SET price=90 WHERE id=oid;
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org AND kind='order_payment_received'),2::bigint,'reprice/recalculation cannot invent income');
 PERFORM public.apply_transaction_pairing(movement,other_pi,'test','system');
 PERFORM assert_true(EXISTS(SELECT 1 FROM public.notification_center_events WHERE data->>'paymentFact'='transaction:'||movement AND data->>'orderId'=oid::text AND status='resolved'),'reassignment invalidates original unmailed contribution');
 PERFORM assert_true(EXISTS(SELECT 1 FROM public.notification_center_events WHERE data->>'paymentFact'='transaction:'||movement AND data->>'orderId'=other_order::text AND data->'reassigned'='true'::jsonb),'new assignment is labelled as already-received money');
 PERFORM public.apply_transaction_pairing(movement,NULL,'test','system');
 PERFORM public.apply_transaction_pairing(movement,other_pi,'test','system');
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org AND kind='order_payment_received'),3::bigint,'detach/reattach preserves fact identity');
 SELECT count(*) INTO n FROM public.notification_center_events WHERE organization=org;
 BEGIN
  INSERT INTO eshop.transactions(amount,currency,bank_account_id,date,transaction_type) VALUES(5,'CZK',bank,now(),'manual') RETURNING id INTO movement;
  PERFORM public.apply_transaction_pairing(movement,pi,'test','system');
  RAISE EXCEPTION 'rollback fixture';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'rollback fixture' THEN RAISE; END IF; END;
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org),n,'rolled-back financial fact cannot publish a phantom');
 PERFORM public.notification_center_payment_problem_internal(oid,true,'financial_conflict');
 PERFORM public.notification_center_payment_problem_internal(oid,true,'action_required');
 PERFORM assert_eq((SELECT count(*) FROM public.notification_center_events WHERE organization=org AND kind='payment_problem'),1::bigint,'changed problem reason retains episode');
 PERFORM public.notification_center_payment_problem_internal(oid,false,NULL);
 PERFORM assert_true(EXISTS(SELECT 1 FROM public.notification_center_events WHERE organization=org AND kind='payment_problem' AND status='recovered'),'payment domain owns recovery');
END $$;
ROLLBACK;
